import pandas as pd
import requests
import json
import re
from datetime import datetime, timezone

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

MAX_ITEMS_PER_RUN = 40
REQUEST_TIMEOUT = 20
ARCHIVE_ORG_QUERY = 'mediatype:movies'
BASE_SEARCH = 'https://archive.org/advancedsearch.php'
BASE_DETAILS = 'https://archive.org/details/'
BASE_THUMB = 'https://archive.org/services/img/'

EXPECTED_COLUMNS = [
    '_epoch', 'discovered_at_epoch', 'source',
    'video_external_id', 'video_url', 'title',
    'channel_id', 'channel_name', 'channel_url',
    'published_iso', 'description',
    'duration_seconds', 'thumbnail_url', 'raw_blob',
]


def info_row(detail):
    return {
        '_epoch': now_epoch,
        'discovered_at_epoch': now_epoch,
        'source': 'archive_org_info',
        'video_external_id': '',
        'video_url': '',
        'title': detail[:400],
        'channel_id': '',
        'channel_name': '',
        'channel_url': '',
        'published_iso': '',
        'description': '',
        'duration_seconds': None,
        'thumbnail_url': '',
        'raw_blob': '',
    }


def first_value(v):
    if v is None:
        return ''
    if isinstance(v, list):
        if len(v) > 0 and v[0] is not None:
            return str(v[0]).strip()
        return ''
    return str(v).strip()


def parse_runtime(rt):
    if not rt:
        return None
    s = str(rt).strip()
    if not s:
        return None
    parts = s.split(':')
    if len(parts) == 3:
        try:
            return int(parts[0]) * 3600 + int(parts[1]) * 60 + int(parts[2])
        except ValueError:
            return None
    if len(parts) == 2:
        try:
            return int(parts[0]) * 60 + int(parts[1])
        except ValueError:
            return None
    if len(parts) == 1:
        try:
            return int(parts[0])
        except ValueError:
            return None
    return None


def slugify_creator(name):
    if not name:
        return ''
    lowered = name.lower().strip()
    cleaned = re.sub(r'[^a-z0-9]+', '_', lowered)
    cleaned = cleaned.strip('_')
    return cleaned[:120]


params = {
    'q': ARCHIVE_ORG_QUERY,
    'output': 'json',
    'rows': str(MAX_ITEMS_PER_RUN),
    'sort[]': 'publicdate desc',
    'fl[]': [
        'identifier', 'title', 'description', 'creator',
        'date', 'publicdate', 'downloads', 'runtime',
    ],
}

try:
    resp = requests.get(BASE_SEARCH, params=params, timeout=REQUEST_TIMEOUT)
except requests.exceptions.RequestException:
    df = pd.DataFrame(
        [info_row('Archive.org request failed (network error).')],
        columns=EXPECTED_COLUMNS,
    )
    GENERATE_RESULTS(df)
else:
    if resp.status_code != 200:
        df = pd.DataFrame(
            [info_row(
                'Archive.org returned HTTP ' + str(resp.status_code)
                + ' (rate-limited or transient). Will retry next cron fire.'
            )],
            columns=EXPECTED_COLUMNS,
        )
        GENERATE_RESULTS(df)
    else:
        try:
            payload = resp.json()
        except ValueError:
            payload = None

        if not payload or not isinstance(payload, dict):
            df = pd.DataFrame(
                [info_row('Archive.org returned non-JSON or empty body.')],
                columns=EXPECTED_COLUMNS,
            )
            GENERATE_RESULTS(df)
        else:
            response_obj = payload.get('response') or {}
            docs = response_obj.get('docs') or []
            if not isinstance(docs, list):
                docs = []

            rows = []
            seen_ids = set()
            for di in range(len(docs)):
                doc = docs[di]
                if not isinstance(doc, dict):
                    continue

                eid = first_value(doc.get('identifier'))
                if not eid:
                    continue
                if eid in seen_ids:
                    continue
                seen_ids.add(eid)

                title = first_value(doc.get('title'))
                description = first_value(doc.get('description'))
                creator = first_value(doc.get('creator'))
                publicdate_str = first_value(doc.get('publicdate'))
                date_field = first_value(doc.get('date'))
                runtime_str = first_value(doc.get('runtime'))
                duration = parse_runtime(runtime_str)

                published_epoch = now_epoch
                if publicdate_str:
                    try:
                        iso_norm = publicdate_str.replace('Z', '+00:00')
                        dt_obj = datetime.fromisoformat(iso_norm)
                        if dt_obj.tzinfo is None:
                            dt_obj = dt_obj.replace(tzinfo=timezone.utc)
                        published_epoch = int(dt_obj.timestamp())
                    except ValueError:
                        pass

                creator_slug = slugify_creator(creator)
                if creator_slug:
                    channel_id = 'archive_org:' + creator_slug
                else:
                    channel_id = 'archive_org:unknown'

                raw_blob_str = json.dumps(doc)

                rows.append({
                    '_epoch': published_epoch,
                    'discovered_at_epoch': now_epoch,
                    'source': 'archive_org',
                    'video_external_id': eid,
                    'video_url': BASE_DETAILS + eid,
                    'title': title[:500],
                    'channel_id': channel_id[:200],
                    'channel_name': (creator or '')[:200],
                    'channel_url': '',
                    'published_iso': publicdate_str or date_field,
                    'description': description[:1000],
                    'duration_seconds': duration,
                    'thumbnail_url': BASE_THUMB + eid,
                    'raw_blob': raw_blob_str[:5000],
                })

            if len(rows) == 0:
                df = pd.DataFrame(
                    [info_row(
                        'Archive.org returned 0 items for query "'
                        + ARCHIVE_ORG_QUERY + '". numFound='
                        + str(response_obj.get('numFound') or 0)
                    )],
                    columns=EXPECTED_COLUMNS,
                )
            else:
                df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
            GENERATE_RESULTS(df)
